:1,"isFinal":false,"scoreA":0,"scoreB":1,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":1,"winnerToKey":"gf","winnerToSlot":"b","eliminatedTeam":"Новогодние рачки","sortOrder":10},{"slug":"ls-fastcup-8","matchKey":"gf","stage":"Гранд-финал","groupName":null,"teamA":"2Girls1FastCup","teamB":"We`re going to live","bestOf":3,"scheduledAt":"2024-12-08T20:45:00+03:00","bracketSide":"grand_final","bracketSlot":1,"isFinal":true,"scoreA":0,"scoreB":2,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":2,"eliminatedTeam":"2Girls1FastCup","sortOrder":11},{"slug":"ls-fastcup-9","matchKey":"g1-1","stage":"Групповой этап · Тур 1","groupName":"Общая группа","teamA":"MY HOMIES","teamB":"Team Amplify","bestOf":1,"scheduledAt":"2025-02-15T19:30:00+03:00","bracketRound":1,"bracketSide":"group","bracketSlot":1,"scoreA":1,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"sortOrder":1},{"slug":"ls-fastcup-9","matchKey":"g2-1","stage":"Групповой этап · Тур 2","groupName":"Общая группа","teamA":"MY HOMIES","teamB":"TEAM SWEETBUBBLES","bestOf":1,"scheduledAt":"2025-02-15T20:45:00+03:00","bracketRound":2,"bracketSide":"group","bracketSlot":1,"scoreA":1,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"sortOrder":2},{"slug":"ls-fastcup-9","matchKey":"g3-1","stage":"Групповой этап · Тур 3","groupName":"Общая группа","teamA":"TEAM SWEETBUBBLES","teamB":"Team Amplify","bestOf":1,"scheduledAt":"2025-02-15T22:00:00+03:00","bracketRound":3,"bracketSide":"group","bracketSlot":1,"scoreA":0,"scoreB":1,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"sortOrder":3},{"slug":"ls-fastcup-9","matchKey":"sf1","stage":"Плей-офф · Полуфинал","groupName":null,"teamA":"Team Amplify","teamB":"TEAM SWEETBUBBLES","bestOf":1,"scheduledAt":"2025-02-16T19:30:00+03:00","bracketSide":"upper","bracketSlot":1,"isFinal":false,"scoreA":1,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":1,"winnerToKey":"gf","winnerToSlot":"b","eliminatedTeam":"TEAM SWEETBUBBLES","sortOrder":4},{"slug":"ls-fastcup-9","matchKey":"gf","stage":"Гранд-финал","groupName":null,"teamA":"MY HOMIES","teamB":"Team Amplify","bestOf":3,"scheduledAt":"2025-02-16T20:45:00+03:00","bracketSide":"grand_final","bracketSlot":1,"isFinal":true,"scoreA":0,"scoreB":2,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":2,"eliminatedTeam":"MY HOMIES","sortOrder":5}]
$matches$::jsonb) AS source(
  slug TEXT, "matchKey" TEXT, "scheduledAt" TIMESTAMPTZ, stage TEXT,
  "groupName" TEXT, "teamA" TEXT, "teamB" TEXT,
  "scoreA" SMALLINT, "scoreB" SMALLINT, "bestOf" SMALLINT,
  "resultType" TEXT, "labelA" TEXT, "labelB" TEXT, "decisionNote" TEXT,
  "bracketRound" SMALLINT, "bracketSide" TEXT, "bracketSlot" SMALLINT,
  "winnerToKey" TEXT, "winnerToSlot" CHAR(1),
  "loserToKey" TEXT, "loserToSlot" CHAR(1),
  "eliminatedTeam" TEXT, "sortOrder" SMALLINT, "isFinal" BOOLEAN
);

INSERT INTO tournament_matches (
  tournament_id, group_id, scheduled_at, stage,
  team_a_application_id, team_b_application_id,
  team_a_score, team_b_score, best_of, status, sort_order,
  result_type, team_a_result_label, team_b_result_label, decision_note,
  bracket_round, bracket_side, bracket_slot,
  eliminated_team_application_id
)
SELECT
  tournament.id, tournament_group.id, source."scheduledAt", source.stage,
  team_a.id, team_b.id, source."scoreA", source."scoreB", source."bestOf",
  'finished', source."sortOrder", source."resultType", source."labelA",
  source."labelB", source."decisionNote", source."bracketRound",
  source."bracketSide", source."bracketSlot", eliminated_team.id
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications team_a
  ON team_a.tournament_id = tournament.id AND team_a.team_name = source."teamA"
JOIN tournament_team_applications team_b
  ON team_b.tournament_id = tournament.id AND team_b.team_name = source."teamB"
LEFT JOIN tournament_groups tournament_group
  ON tournament_group.tournament_id = tournament.id
 AND tournament_group.name = source."groupName"
LEFT JOIN tournament_team_applications eliminated_team
  ON eliminated_team.tournament_id = tournament.id
 AND eliminated_team.team_name = source."eliminatedTeam"
WHERE NOT EXISTS (
  SELECT 1 FROM tournament_matches existing
  WHERE existing.tournament_id = tournament.id
    AND existing.sort_order = source."sortOrder"
);

UPDATE tournament_matches source_match
SET winner_to_match_id = winner_match.id,
    winner_to_slot = source."winnerToSlot",
    loser_to_match_id = loser_match.id,
    loser_to_slot = source."loserToSlot"
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
LEFT JOIN imported_fastcup_matches winner_source
  ON winner_source.slug = source.slug AND winner_source."matchKey" = source."winnerToKey"
LEFT JOIN tournament_matches winner_match
  ON winner_match.tournament_id = tournament.id
 AND winner_match.sort_order = winner_source."sortOrder"
LEFT JOIN imported_fastcup_matches loser_source
  ON loser_source.slug = source.slug AND loser_source."matchKey" = source."loserToKey"
LEFT JOIN tournament_matches loser_match
  ON loser_match.tournament_id = tournament.id
 AND loser_match.sort_order = loser_source."sortOrder"
WHERE source_match.tournament_id = tournament.id
  AND source_match.sort_order = source."sortOrder";

CREATE TEMP TABLE imported_fastcup_rules ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($rules$
[{"slug":"ls-fastcup-6","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (тут)"},{"slug":"ls-fastcup-6","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"ММР игроков\", там отмечаются только игроки, прошедшие \"Отметку ММР-показателя\", игроки не прошедшие отметку не допускаются до турнира."},{"slug":"ls-fastcup-6","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-6","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" - игрок, не заигранный на серверных сезонных ивентах, допуск таких игроков на усмотрение организатора, перед регистрацией таких игроков кандидатуру нужно одобрить у организатора, предоставив всю доступную информацию по аккаунту игрока."},{"slug":"ls-fastcup-6","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной. Возможны исключения, при которых замены сверх одной сделанной предоставляются организатором. Замена должна быть согласована и ММР замены не должен превышать ММР заменяемого игрока."},{"slug":"ls-fastcup-6","sortOrder":6,"ruleText":"На турнире предусмотрено 6 слотов для команд. Если команд будет более 6, 7 и последующие команды, отправившие регистрационную форму, не попадут на турнир."},{"slug":"ls-fastcup-6","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм с задержкой для зрителей 5 минуты (с билетом). Капитаны команд обязаны получить билет у организатора до старта турнира."},{"slug":"ls-fastcup-6","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-6","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 15 минут без штрафа. Опоздание от 15 до 30 минут - оппонент выбирает вам героя на последний пик из 3-х предложенных вами оппоненту."},{"slug":"ls-fastcup-6","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-6","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-6","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-6","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-6","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-6","sortOrder":15,"ruleText":"Легионерами считаются игроки не игравшие в матчи CD и CM лиг в DPC межсезонье и не принимавшие участия в 1-м туре лиги 5-го сезона"},{"slug":"ls-fastcup-7","sortOrder":1,"ruleText":"https://forms.gle/uZynoCt9qkfQK9sW6Регистрация на турнир проходит через форму (тут)"},{"slug":"ls-fastcup-7","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"ММР игроков\", там отмечаются только игроки, прошедшие \"Отметку ММР-показателя\", игроки не прошедшие отметку не допускаются до турнира."},{"slug":"ls-fastcup-7","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-7","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - два слота в команде может занять \"легионер\" (см п.14)"},{"slug":"ls-fastcup-7","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной. Возможны исключения, при которых замены сверх одной сделанной предоставляются организатором. Замена должна быть согласована и ММР замены не должен превышать ММР заменяемого игрока."},{"slug":"ls-fastcup-7","sortOrder":6,"ruleText":"На турнире предусмотрено 4 слотов для команд. Если команд будет больше предусмотренного 5, 6 и последующие команды, отправившие регистрационную форму, не попадут на турнир. Формат может быть изменен."},{"slug":"ls-fastcup-7","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм с задержкой для зрителей 5 минуты (с билетом). Капитаны команд обязаны получить билет у организатора до старта турнира."},{"slug":"ls-fastcup-7","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-7","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - штраф бонусного времени на первые две карты серии 3-го уровня. Опоздание от 20 до 30 минут - штраф бонусного времени на первые две карты серии 3-го уровня, выбор стороны или очереди пика на первых двух картах достаются оппоненту. Опоздание более чем на 30 минут - техническое поражение на первой карте и штраф бонусного времени 3-го уровня и выбор стороны или очереди пика на достаются оппоненту на оставшихся картах."},{"slug":"ls-fastcup-7","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-7","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-7","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-7","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-7","sortOrder":14,"ruleText":"Легионерами считаются игроки не отыгравшие 3 и более матчей в серверной лиге 5-го сезона и менее 100 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-7","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-8","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (тут)"},{"slug":"ls-fastcup-8","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"ММР игроков\", там отмечаются только игроки, прошедшие \"Отметку ММР-показателя\", игроки не прошедшие отметку не допускаются до турнира."},{"slug":"ls-fastcup-8","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-8","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - два слота в команде может занять \"легионер\" (см п.14)"},{"slug":"ls-fastcup-8","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной. Возможны исключения, при которых замены сверх одной сделанной предоставляются организатором. Замена должна быть согласована и ММР замены не должен превышать ММР заменяемого игрока."},{"slug":"ls-fastcup-8","sortOrder":6,"ruleText":"На турнире предусмотрено 4 слотов для команд. Если команд будет больше предусмотренного 5, 6 и последующие команды, отправившие регистрационную форму, не попадут на турнир. Формат может быть изменен."},{"slug":"ls-fastcup-8","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм в закрытом для зрителей формате (турнирного билета нет)."},{"slug":"ls-fastcup-8","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-8","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - штраф бонусного времени на первые две карты серии 2-го уровня. Опоздание от 20 до 30 минут - штраф бонусного времени на первые две карты серии 3-го уровня, выбор стороны или очереди пика на первых двух картах достаются оппоненту. Опоздание более чем на 30 минут - техническое поражение на первой карте и штраф бонусного времени 3-го уровня и выбор стороны или очереди пика на достаются оппоненту на оставшихся картах."},{"slug":"ls-fastcup-8","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-8","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-8","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-8","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-8","sortOrder":14,"ruleText":"Легионерами считаются игроки не заигранные в серверных ивентах и сыгравшие менее 100 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-8","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-9","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (ТУТ)"},{"slug":"ls-fastcup-9","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"ММР игроков\", там отмечаются только игроки, прошедшие \"Отметку ММР-показателя\", игроки не прошедшие отметку не допускаются до турнира."},{"slug":"ls-fastcup-9","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены 