х достаются оппоненту. Опоздание более чем на 30 минут - техническое поражение на первой карте и штраф бонусного времени 3-го уровня и выбор стороны или очереди пика на достаются оппоненту на оставшихся картах."},{"slug":"ls-fastcup-9","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-9","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-9","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-9","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-9","sortOrder":14,"ruleText":"Легионерами считаются игроки не заигранные в серверных сезонных турнирах и сыгравшие менее 50 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-9","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."}]
$rules$::jsonb) AS source(
  slug TEXT, "sortOrder" SMALLINT, "ruleText" TEXT
);

INSERT INTO tournament_rules (tournament_id, sort_order, rule_text)
SELECT tournament.id, source."sortOrder", source."ruleText"
FROM imported_fastcup_rules source
JOIN tournaments tournament ON tournament.slug = source.slug
ON CONFLICT (tournament_id, sort_order) DO NOTHING;

INSERT INTO tournament_team_results (application_id, placement, result_label)
SELECT application.id, source.placement, source."resultLabel"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
ON CONFLICT (application_id) DO NOTHING;

INSERT INTO tournament_prizes (
  tournament_id, placement, application_id, team_name_snapshot, prize_text
)
SELECT tournament.id, source.placement, application.id,
  source."teamName", source."prizeText"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
WHERE source.placement IS NOT NULL
ON CONFLICT (tournament_id, placement) DO NOTHING;

CREATE TEMP TABLE imported_fastcup_schedule ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($schedule$
